        const fieldForMol = (x, keys, fallback) => { const fromInputs = inputForMol(x.mol, keys); if (fromInputs !== "--") return fromInputs; const fromCat = valOf(x.cat, keys); if (fromCat !== "--") return fromCat; return fallback || "--"; };
